<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-[1400px] space-y-6">
    <PageHeader :title="t('admin_billing.audit_title')" :description="t('admin_billing.audit_desc')" />
    <div class="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-white/5">
      <form class="grid gap-3 border-b border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-4 dark:border-white/10" @submit.prevent="applyFilters"><input v-model="filters.admin_id" type="number" min="1" class="billing-input" :placeholder="t('admin_billing.admin_id')" /><input v-model.trim="filters.organization_id" class="billing-input" :placeholder="t('admin_billing.organization_id')" /><input v-model.trim="filters.action" class="billing-input" :placeholder="t('admin_billing.action_placeholder')" /><input v-model.trim="filters.target_type" class="billing-input" :placeholder="t('admin_billing.target_type')" /><input v-model.trim="filters.target_id" class="billing-input" :placeholder="t('admin_billing.target_id')" /><input v-model="filters.date_from" type="date" class="billing-input" :title="t('admin_billing.from_date')" /><input v-model="filters.date_to" type="date" class="billing-input" :title="t('admin_billing.to_date')" /><div class="flex gap-2"><button class="flex-1 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-bold text-white dark:bg-white dark:text-slate-900">{{ t('admin_billing.filter') }}</button><button type="button" class="rounded-xl border border-slate-200 px-3 dark:border-white/10" :title="t('admin_billing.filter_off')" @click="resetFilters"><span class="material-symbols-outlined">filter_alt_off</span></button></div></form>
      <PageState :loading="loading" :error="error" :empty="!logs.length" :empty-text="t('admin_billing.audit_no_logs')" @retry="load"><div class="overflow-x-auto"><table class="min-w-[1150px] w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-black/20 dark:text-slate-400"><tr><th class="p-4">{{ t('admin_billing.header_time_short') }}</th><th class="p-4">{{ t('admin_billing.header_admin') }}</th><th class="p-4">{{ t('admin_billing.header_action') }}</th><th class="p-4">{{ t('admin_billing.header_target') }}</th><th class="p-4">{{ t('admin_billing.organization_id') }}</th><th class="p-4">{{ t('admin_billing.header_reason') }}</th><th class="p-4 text-right">{{ t('admin_billing.details') }}</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-white/5"><tr v-for="log in logs" :key="log.id"><td class="p-4 whitespace-nowrap">{{ formatBillingDate(log.created_at, true) }}</td><td class="p-4"><p class="font-semibold dark:text-white">{{ log.admin?.name || '—' }}</p><p class="text-xs text-slate-500">{{ log.admin?.email || '—' }}</p></td><td class="p-4"><code class="text-xs text-cyan-700 dark:text-cyan-300">{{ log.action }}</code></td><td class="p-4"><p>{{ log.target_type }}</p><p class="max-w-48 truncate font-mono text-xs text-slate-500" :title="log.target_id">{{ log.target_id }}</p></td><td class="p-4 max-w-48 truncate font-mono text-xs" :title="log.organization_id || ''">{{ log.organization_id || '—' }}</td><td class="p-4 max-w-sm"><p class="line-clamp-2" :title="log.reason || ''">{{ log.reason || '—' }}</p></td><td class="p-4 text-right"><NuxtLink :to="`/admin/billing/audit-logs/${log.id}`" class="inline-flex rounded-lg border border-slate-200 p-2 hover:border-cyan-400 hover:text-cyan-600 dark:border-white/10" :title="t('admin_billing.details')"><span class="material-symbols-outlined text-lg">visibility</span></NuxtLink></td></tr></tbody></table></div><Pagination :pagination="pagination" @change="changePage" /></PageState>
    </div>
  </div></div>
</template>

<script setup lang="ts">
import type { BillingAuditLog, BillingPagination } from '~/types/admin-billing'; import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import Pagination from '~/components/admin/billing/Pagination.vue'; import { formatBillingDate } from '~/utils/adminBilling'
const { t } = useI18n()
definePageMeta({ layout: 'layout-admin' }); const api = useAdminBilling(); const logs = ref<BillingAuditLog[]>([]); const pagination = ref<BillingPagination>({ current_page: 1, per_page: 20, total: 0, last_page: 1 }); const defaults = () => ({ admin_id: '', organization_id: '', action: '', target_type: '', target_id: '', date_from: '', date_to: '', page: 1, per_page: 20 }); const filters = reactive(defaults()); const loading = ref(true); const error = ref('')
const load = async () => { loading.value = true; error.value = ''; try { const response = await api.listAuditLogs(filters); logs.value = response.data; pagination.value = response.pagination } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }; const applyFilters = () => { filters.page = 1; load() }; const resetFilters = () => { Object.assign(filters, defaults()); load() }; const changePage = (page: number) => { filters.page = page; load() }; onMounted(load)
</script>
<style scoped>.billing-input{ @apply w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-cyan-500 dark:border-white/10 dark:bg-black/20 dark:text-white; }</style>
